<script setup lang="ts">
import { computed, reactive, shallowRef, watch } from "vue";
import type { ResultFilterValues } from "../../api/literatureSearch";
const props = defineProps<{ filters: ResultFilterValues; facets?: Record<string, Record<string, number>>; filteredTotal: number; disabled: boolean; open: boolean }>();
const emit = defineEmits<{ apply: [filters: ResultFilterValues]; close: [] }>();
const draft = reactive<ResultFilterValues>({ ...props.filters });
const expanded = reactive<Record<string, boolean>>({ cas: false, impact: false, cited: false, fulltext: true, language: false, more: false });
const customYearsOpen = shallowRef(false);
watch(() => props.filters, value => Object.assign(draft, value), { deep: true });
const entries = (name: string) => Object.entries(props.facets?.[name] ?? {}).slice(0, 6);
const selectedCount = computed(() => [draft.year, draft.year_from, draft.publication_type, draft.journal, draft.cas_quartile, draft.impact_factor_min, draft.cited_by_min, draft.has_abstract, draft.saved, draft.read_status].filter(value => value !== null && value !== "" && value !== undefined).length);
function reset(){ Object.assign(draft,{year:null,year_from:null,year_to:null,publication_type:"",journal:"",author:"",has_abstract:null,saved:null,read_status:"",tags:"",jcr_quartile:"",wos_index:"",cas_quartile:"",impact_factor_min:null,cited_by_min:null,sort:props.filters.sort}); emit("apply",{...draft}); }
function submit(){ emit("apply", { ...draft }); }
function applyPatch(patch: Partial<ResultFilterValues>){ Object.assign(draft, patch); submit(); }
function toggleYear(value: string){ const year=Number(value); applyPatch(draft.year===year?{year:null}:{year,year_from:null,year_to:null}); }
function toggleJournal(value: string){ applyPatch({journal:draft.journal===value?"":value}); }
function toggleCas(value: string){ applyPatch({cas_quartile:draft.cas_quartile===value?"":value}); }
function toggleImpact(value: string){ const minimum=Number(value.slice(2)); applyPatch({impact_factor_min:draft.impact_factor_min===minimum?null:minimum}); }
function toggleCitedBy(value: string){ const minimum=Number(value.slice(2)); applyPatch({cited_by_min:draft.cited_by_min===minimum?null:minimum}); }
function toggle(section: string){ expanded[section] = !expanded[section]; }
function setRange(from: number, to: number){ draft.year=null; draft.year_from=Math.min(from,to); draft.year_to=Math.max(from,to); }
function updateFrom(value: number){ setRange(value, draft.year_to ?? 2026); }
function updateTo(value: number){ setRange(draft.year_from ?? 2020, value); }
function applyRange(){ submit(); }
function quickYears(years: number){ setRange(Math.max(2020, 2026 - years + 1), 2026); customYearsOpen.value=false; submit(); }
function resetYears(){ setRange(2020,2026); customYearsOpen.value=false; submit(); }
</script>

<template>
  <aside v-if="open" class="filter-sidebar" aria-label="筛选文献">
    <header><h2>筛选条件 <span>· 已选择 {{ selectedCount }} 项</span></h2><button type="button" @click="reset">重置</button><button class="close" type="button" aria-label="关闭筛选" @click="emit('close')">收起</button></header>
    <form @submit.prevent="submit">
      <fieldset class="year-filter"><legend>发表年份 <button type="button" @click="resetYears">重置</button></legend><div class="year-ends"><span>{{ draft.year_from ?? 2020 }}</span><span>{{ draft.year_to ?? 2026 }}</span></div><div class="year-range"><input aria-label="起始发表年份" type="range" min="2020" max="2026" :value="draft.year_from ?? 2020" @input="updateFrom(Number(($event.target as HTMLInputElement).value))" @change="applyRange"><input aria-label="结束发表年份" type="range" min="2020" max="2026" :value="draft.year_to ?? 2026" @input="updateTo(Number(($event.target as HTMLInputElement).value))" @change="applyRange"></div><div class="quick-years"><button type="button" @click="quickYears(1)">近1年</button><button type="button" @click="quickYears(3)">近3年</button><button type="button" @click="quickYears(5)">近5年</button><button type="button" :aria-expanded="customYearsOpen" @click="customYearsOpen=!customYearsOpen">自定义</button></div><div v-if="customYearsOpen" class="custom-years"><label>起始年<input aria-label="自定义起始年份" type="number" min="2020" max="2026" :value="draft.year_from??2020" @change="updateFrom(Number(($event.target as HTMLInputElement).value));applyRange()"></label><label>结束年<input aria-label="自定义结束年份" type="number" min="2020" max="2026" :value="draft.year_to??2026" @change="updateTo(Number(($event.target as HTMLInputElement).value));applyRange()"></label></div><label v-for="[value,count] in entries('year')" :key="value" class="facet-option"><input type="radio" name="year" :value="value" :checked="draft.year === Number(value)" @click.prevent="toggleYear(value)"> {{ value }} <small>{{ count }}</small></label></fieldset>
      <fieldset><legend>研究类型</legend><label v-for="[value,count] in entries('publication_type')" :key="value"><input type="checkbox" :value="value" :checked="draft.publication_type===value" @change="applyPatch({publication_type:($event.target as HTMLInputElement).checked?value:''})"> {{ value }} <small>{{ count }}</small></label></fieldset>
      <fieldset><legend>期刊</legend><label v-for="[value,count] in entries('journal')" :key="value"><input type="radio" name="journal" :value="value" :checked="draft.journal===value" @click.prevent="toggleJournal(value)"> {{ value }} <small>{{ count }}</small></label></fieldset>
      <fieldset class="collapsed-filter"><legend><button type="button" :aria-expanded="expanded.cas" @click="toggle('cas')">中科院分区 <span>{{ expanded.cas?'⌃':'⌄' }}</span></button></legend><template v-if="expanded.cas"><label v-for="[value,count] in entries('cas')" :key="value"><input type="radio" name="cas" :checked="draft.cas_quartile===value" @click.prevent="toggleCas(value)"> {{ value }} <small>{{ count }}</small></label><p v-if="!entries('cas').length" class="capability-note">当前结果没有可匹配的中科院分区。</p></template></fieldset>
      <fieldset class="collapsed-filter"><legend><button type="button" :aria-expanded="expanded.impact" @click="toggle('impact')">影响因子 <span>{{ expanded.impact?'⌃':'⌄' }}</span></button></legend><template v-if="expanded.impact"><label v-for="[value,count] in entries('impact_factor')" :key="value"><input type="radio" name="impact" :checked="draft.impact_factor_min===Number(value.slice(2))" @click.prevent="toggleImpact(value)"> IF {{ value }} <small>{{ count }}</small></label><p v-if="!entries('impact_factor').length" class="capability-note">当前结果没有可匹配的影响因子。</p></template></fieldset>
      <fieldset class="collapsed-filter"><legend><button type="button" :aria-expanded="expanded.cited" @click="toggle('cited')">被引次数 <span>{{ expanded.cited?'⌃':'⌄' }}</span></button></legend><template v-if="expanded.cited"><label v-for="[value,count] in entries('cited_by')" :key="value"><input type="radio" name="cited" :checked="draft.cited_by_min===Number(value.slice(2))" @click.prevent="toggleCitedBy(value)"> 被引 {{ value }} <small>{{ count }}</small></label><p v-if="!entries('cited_by').length" class="capability-note">尚无 OpenAlex 文章级被引数据，请先生成评分。</p></template></fieldset>
      <fieldset><legend><button type="button" :aria-expanded="expanded.fulltext" @click="toggle('fulltext')">全文获取 <span>{{ expanded.fulltext?'⌃':'⌄' }}</span></button></legend><label v-if="expanded.fulltext"><input type="checkbox" :checked="draft.has_abstract===true" @change="applyPatch({has_abstract:draft.has_abstract===true?null:true})"> 有摘要</label></fieldset>
      <fieldset v-for="section in [{key:'language',label:'语言'},{key:'more',label:'更多筛选'}]" :key="section.key" class="collapsed-filter"><legend><button type="button" :aria-expanded="expanded[section.key]" @click="toggle(section.key)">{{ section.label }} <span>{{ expanded[section.key]?'⌃':'⌄' }}</span></button></legend><p v-if="expanded[section.key]" class="capability-note">此结果快照暂未提供可筛选的 {{ section.label }} facet。</p></fieldset>
      <fieldset><legend>我的状态</legend><label><input type="checkbox" :checked="draft.saved===true" @change="applyPatch({saved:draft.saved===true?null:true})"> 仅阅读计划</label><label><input type="checkbox" :checked="draft.read_status==='read'" @change="applyPatch({read_status:draft.read_status==='read'?'':'read'})"> 已读</label></fieldset>
      <button class="apply" type="submit" :disabled="disabled" @click="submit">应用筛选 · {{ filteredTotal }} 篇</button>
    </form>
  </aside>
</template>

<style scoped>
.filter-sidebar{width:267px;min-width:267px;box-sizing:border-box;border-left:1px solid #e4ebf4;background:#fff;color:#153b72}.filter-sidebar header{height:57px;display:flex;align-items:center;padding:0 15px;border-bottom:1px solid #e4ebf4}.filter-sidebar h2{margin:0 auto 0 0;font-size:13px}.filter-sidebar h2 span{color:#1760ff;font-size:11px;font-weight:500}.filter-sidebar header button{border:0;background:transparent;color:#1760ff;font-size:11px;cursor:pointer}.close{color:#1760ff!important}form{padding:0 14px 15px;overflow:auto;max-height:calc(100vh - 119px)}fieldset{margin:0;padding:11px 0;border:0;border-bottom:1px solid #e4ebf4}legend{display:flex;justify-content:space-between;width:100%;margin-bottom:7px;color:#163e78;font-size:11px;font-weight:750}legend button{display:flex;justify-content:space-between;width:100%;padding:0;border:0;background:transparent;color:#163e78;font:inherit;cursor:pointer}label{display:flex;align-items:center;gap:6px;margin:6px 0;color:#31517d;font-size:11px}small{margin-left:auto;color:#6f89af}.capability-note{margin:4px 0 0;color:#6f89af;font-size:10px;line-height:15px}.year-ends{display:flex;justify-content:space-between;font-size:10px}.year-range{display:grid;gap:1px;margin:0 2px}.year-range input{width:100%;accent-color:#1760ff}.quick-years{display:grid;grid-template-columns:repeat(4,1fr);gap:4px;margin:4px 0 7px}.quick-years button{height:24px;border:1px solid #d9e5f6;border-radius:4px;background:#fff;color:#2860aa;font-size:10px;cursor:pointer}.custom-years{display:grid;grid-template-columns:1fr 1fr;gap:6px;padding:7px;border-radius:6px;background:#f4f7fc}.custom-years label{display:grid;gap:3px;margin:0;font-size:9px}.custom-years input{width:100%;box-sizing:border-box;border:1px solid #cbdcf2;border-radius:4px;padding:4px;color:#153b72}.facet-option{display:none}.collapsed-filter{padding:10px 0}.apply{position:sticky;bottom:0;width:100%;margin-top:13px;height:38px;border:0;border-radius:5px;background:#1760ff;color:#fff;font-size:12px;font-weight:750;cursor:pointer;box-shadow:0 -6px 14px #fff}@media(max-width:1199px){.filter-sidebar{position:fixed;z-index:12;right:0;top:62px;bottom:0;box-shadow:-10px 0 30px #17233b18}}@media(max-width:640px){.filter-sidebar{width:min(90vw,320px);min-width:0}}
</style>
